class MinHeap:
    def __init__(self):
        self.heap = []
        self.pos = {}  # value -> index mapping for O(1) decrease_key lookup

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]
        self.pos[self.heap[i][1]] = i
        self.pos[self.heap[j][1]] = j

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self.heap[i][0] < self.heap[parent][0]:
                self._swap(i, parent)
                i = parent
            else:
                break

    def _sift_down(self, i):
        n = len(self.heap)
        while True:
            smallest = i
            left = 2 * i + 1
            right = 2 * i + 2
            if left < n and self.heap[left][0] < self.heap[smallest][0]:
                smallest = left
            if right < n and self.heap[right][0] < self.heap[smallest][0]:
                smallest = right
            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break

    def insert(self, value, key):
        """Insert an item with the given key (priority). O(log n)"""
        entry = [key, value]
        self.heap.append(entry)
        idx = len(self.heap) - 1
        self.pos[value] = idx
        self._sift_up(idx)

    def peek(self):
        """Return (key, value) of the minimum element without removing it. O(1)"""
        if not self.heap:
            raise IndexError("peek from empty heap")
        return tuple(self.heap[0])

    def extract_min(self):
        """Remove and return (key, value) of the minimum element. O(log n)"""
        if not self.heap:
            raise IndexError("extract from empty heap")
        self._swap(0, len(self.heap) - 1)
        key, value = self.heap.pop()
        del self.pos[value]
        if self.heap:
            self._sift_down(0)
        return (key, value)

    def decrease_key(self, value, new_key):
        """Decrease the key of the given value. O(log n)"""
        if value not in self.pos:
            raise KeyError(f"value {value!r} not in heap")
        idx = self.pos[value]
        if new_key > self.heap[idx][0]:
            raise ValueError("new key is greater than current key")
        self.heap[idx][0] = new_key
        self._sift_up(idx)

    def __len__(self):
        return len(self.heap)

    def __bool__(self):
        return bool(self.heap)


if __name__ == "__main__":
    h = MinHeap()
    h.insert("task_c", 30)
    h.insert("task_a", 10)
    h.insert("task_b", 20)
    h.insert("task_d", 40)

    print("peek:", h.peek())          # (10, 'task_a')
    print("extract:", h.extract_min()) # (10, 'task_a')
    print("extract:", h.extract_min()) # (20, 'task_b')

    h.decrease_key("task_d", 5)
    print("after decrease_key(task_d, 5):")
    print("extract:", h.extract_min()) # (5, 'task_d')
    print("extract:", h.extract_min()) # (30, 'task_c')
